const diagnostics=new WeakMap<Page,{errors:string[];console:unknown[]}>();
function listen(page:Page){if(diagnostics.has(page))return;const rows={errors:[] as string[],console:[] as unknown[]};diagnostics.set(page,rows);page.on('pageerror',e=>rows.errors.push(e.message));page.on('console',e=>{if(e.type()==='error'||e.type()==='warning')rows.console.push({type:e.type(),text:e.text()});});}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({context},info)=>{for(const [i,p]of context.pages().entries())if(!p.isClosed()){await p.evaluate(()=>{const w=window as any;w.__ta09ReleaseWrite?.();w.__ta09RestorePut?.();w.__ta09ReleaseMetadata?.();w.__ta09RestoreMetadata?.();w.__ta09Observer?.disconnect();w.__ta09RestoreVisibility?.();});await info.attach('ta09-browser-diagnostics-'+i,{body:JSON.stringify(diagnostics.get(p)??{errors:[],console:[]}),contentType:'application/json'});expect(diagnostics.get(p)?.errors??[]).toEqual([]);}});
async function attach(info:TestInfo,name:string,data:unknown){await info.attach(name,{body:JSON.stringify(data),contentType:'application/json'});}
async function database(page:Page){return page.evaluate(()=>new Promise<any>((accept,reject)=>{
 const request=indexedDB.open('chenyuan-playable-v1');request.onupgradeneeded=()=>{request.transaction!.abort();reject(new Error('TA09 readonly observer must not create a Game database'));};request.onerror=()=>reject(request.error);
 request.onsuccess=()=>{const db=request.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};for(const name of db.objectStoreNames){rows[name]=[];const q=tx.objectStore(name).openCursor();q.onsuccess=()=>{if(q.result){rows[name].push({key:q.result.key,value:q.result.value});q.result.continue();}};}tx.oncomplete=()=>{db.close();accept({version:db.version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};
}));}
function goldenFixture():Game{const d=driver('leave','sword');d.realm();d.realm();d.funds(1000);d.go('sect');validateGame(d.game);return structuredClone(d.game) as Game;}
async function load(page:Page,game:Game,virtual=true,replaceExisting=false){
 listen(page);if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.locator('.app-shell')).toHaveAttribute('data-font-scale','1');let input=page.getByLabel('导入已有存档',{exact:true});let confirmation:string|null=null;
 if(replaceExisting){await expect(page.getByTestId('save-status')).toHaveText('已保存');await page.getByRole('button',{name:'设置',exact:true}).click();input=page.getByTestId('import');}
 await expect(input).toBeEnabled();const initial=await database(page);if(replaceExisting)expect(stateValue(initial,'current')).not.toBeNull();await input.setInputFiles({name:'lawful-ta09-golden-prefix.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(game))});if(replaceExisting){await expect(page.getByTestId('game-confirmation-message')).toContainText('导入将替换当前进度。建议先导出备份，再明确确认本次覆盖。');confirmation=await page.getByTestId('game-confirmation-message').innerText();await answerGameConfirmation(page,'import');}await expect(page.getByTestId('action-execution')).toBeVisible();if(replaceExisting)expect(confirmation).toContain('导入将替换当前进度。建议先导出备份，再明确确认本次覆盖。');if(virtual){await expect(page.getByTestId('action-countdown')).toHaveText('0.6 秒');await page.clock.runFor(599);expect(await database(page)).toEqual(initial);await page.clock.runFor(1);}await expect(page.getByTestId('save-status')).toHaveText('已保存');if(replaceExisting&&await page.getByRole('button',{name:'关闭设置',exact:true}).isVisible())await page.getByRole('button',{name:'关闭设置',exact:true}).click();
 const before=await snapshot(page) as Game,expected=structuredClone(game);expected.core.runId=before.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=before.core.runId+':'+expected.core.activeEvent.id;expect(before).toEqual(expected);expect(await activity(page)).toBeNull();return before;
}

const jadeForms:Record<string,string>={sword_mind:'heart',sword_still:'heart',sword_build:'blade',sword_guard:'blade',sword_release:'scroll',sword_echo:'scroll',talisman_mind:'knot',talisman_calm:'knot',talisman_build:'seal',talisman_frost:'seal',talisman_release:'fan',talisman_return:'fan'};
