function preparedFixture(relicId?:string,all=false,school:'sword'|'talisman'='sword'):Game{
 const d=driver('leave',school);d.realm();d.realm();d.funds(2000);
 if(all)for(const [id,s]of Object.entries(C.skills))if(!d.game.learned.includes(id)){d.funds(s.price);d.go('sect');d.doAction({type:'LEARN',skill:id});}
 for(const id of all?Object.keys(C.relics):relicId?[relicId]:[]){for(const [item,n]of Object.entries(C.relics[id].inputs))d.resource(item,n);d.funds(C.relics[id].stones);if(all){d.go('cave');d.doAction({type:'FORGE',relic:id});}}
 d.go(relicId||all?'cave':'sect');validateGame(d.game);return structuredClone(d.game) as Game;
}
async function isolatedDiagnostics(page:Page,info:TestInfo){await page.evaluate(()=>{const w=window as any;w.__ta09ReleaseWrite?.();w.__ta09ReleaseMetadata?.();w.__ta09RestoreMetadata?.();w.__ta09RestorePut?.();w.__ta09RestoreVisibility?.();w.__ta09Observer?.disconnect();});await attach(info,'ta09-isolated-context-diagnostics',diagnostics.get(page)??{errors:[],console:[]});expect(diagnostics.get(page)?.errors??[]).toEqual([]);}
async function skills(page:Page,id='sword_guard'){await openHubFeature(page,'skills');await page.getByTestId('equipment-mode-skills').click();await openLearningLibrary(page);await page.getByLabel('功法流派',{exact:true}).selectOption('all');await openLearningLibrary(page);await page.getByLabel('显示后续功法法宝',{exact:true}).check();await selectLearningSkill(page,id);}
