async function learnPlan(page:Page,ids:string[],budget=ids.reduce((n,id)=>n+C.skills[id].price,0),reserve=0){await skills(page,ids[0]??'sword_guard');for(const id of ids){await selectLearningSkill(page,id);await page.getByTestId('learn-'+id).click();}await openLearningSettings(page);await page.getByLabel('累计研习灵石预算').fill(String(budget));await page.getByLabel('研习灵石保留量').fill(String(reserve));await closeLearningSettings(page);}
async function running(page:Page,kind:'learn'|'study'|'forge',virtual=true){await expect.poll(async()=>(await activity(page))?.status).toBe('running');const a=await activity(page);expect(a.version).toBe(kind==='forge'?4:5);expect(a.plan.kind).toBe(kind);expect(a.cycleMs).toBe(kind==='learn'?30000:60000);await expect(page.locator('[data-testid=training-activity][data-running=true][data-generation="'+a.generation+'"]')).toBeVisible();if(virtual)await expect(page.getByTestId('training-countdown')).toHaveText((a.cycleMs/1000).toFixed(1)+' 秒');else{const n=parseFloat(await page.getByTestId('training-countdown').innerText());expect(n).toBeGreaterThan(0);expect(n).toBeLessThanOrEqual(a.cycleMs/1000);const live=await activity(page);expect(live.id).toBe(a.id);expect(live.generation).toBe(a.generation);expect(live.nextCommand).toEqual(a.nextCommand);expect(live.status).toBe('running');}return a;}
async function begin(page:Page,kind:'learn'|'study'|'forge',virtual=true){await closeLearningSettings(page);await page.getByTestId(kind==='forge'?'production-start':'preparation-start').click();return running(page,kind,virtual);}
async function saved(page:Page,a:any,before:Game,accepted:any,info:TestInfo,name:string){
 await expect.poll(async()=>(await activity(page))?.completedCycles).toBe(a.completedCycles+1);await expect(page.getByTestId('save-status')).toHaveText('已保存');const raw=await database(page),after=await snapshot(page) as Game,formal=resolve(before,a.nextCommand),key=a.runId+':'+a.nextCommand.commandId,rows=raw.rows['full-receipts'].filter((r:any)=>r.key===key);expect(raw.version).toBe(9);expect(after).toEqual(formal.nextState);expect(stateValue(raw,'current')).toEqual(after);expect(stateValue(raw,'previous')).toEqual(before);expect(rows).toHaveLength(1);const receipt=rows[0].value;
 const input={kind:'TICK',tick:{commandId:a.nextCommand.commandId,runId:a.runId,expectedRevision:a.gameRevision,activityId:a.id,expectedActivityRevision:a.revision,ownerId:a.ownerId,generation:a.generation}};expect(receipt.format).toBe('chenyuan-activity-receipt');expect(receipt.input).toEqual(input);expect(receipt.fingerprint).toBe(canonicalFingerprint(input));expect(receipt.command).toEqual(a.nextCommand);expect(receipt.result).toEqual(formal.result);
 let reconstructionNow:number;
 if(a.version===5){expect(receipt.version).toBe(2);expect(Object.keys(receipt).sort()).toEqual(['format','version','input','fingerprint','activity','command','result','proof'].sort());expect(receipt.proof.activityBefore).toEqual(a);expect(receipt.proof.stateAfter).toEqual(after);expect(receipt.proof.resolvedAt).toBeGreaterThanOrEqual(a.dueAt);reconstructionNow=receipt.proof.resolvedAt;}
 else{expect(a.version).toBe(4);expect(receipt.version).toBe(1);expect(Object.keys(receipt).sort()).toEqual(['format','version','input','fingerprint','activity','command','result'].sort());expect(receipt).not.toHaveProperty('proof');reconstructionNow=receipt.activity.status==='running'?receipt.activity.startedAt:a.dueAt;}
 expect(Number.isSafeInteger(reconstructionNow)).toBe(true);expect(reconstructionNow).toBeGreaterThanOrEqual(a.dueAt);const done=completeActivity(after,a,formal.result,{commandId:a.nextCommand.commandId,now:reconstructionNow});expect(stateValue(raw,'activity')).toEqual(done);expect(await activity(page)).toEqual(done);expect(receipt.activity).toEqual(done);expect(()=>validateActivityReceipt(receipt,after)).not.toThrow();expect(raw.rows['full-receipts'].filter((r:any)=>r.key!==key)).toEqual(accepted.rows['full-receipts']);expect(raw.rows['full-state'].filter((r:any)=>!['current','previous','activity'].includes(r.key))).toEqual(accepted.rows['full-state'].filter((r:any)=>!['current','previous','activity'].includes(r.key)));for(const store of Object.keys(accepted.rows).filter(n=>!['full-state','full-receipts'].includes(n)))expect(raw.rows[store],store).toEqual(accepted.rows[store]);const proof={a,before,accepted,after,formal,done,raw,key,receipt,reconstructionNow,v4StoppedTimeIsOnlyAReconstruction:a.version===4};await attach(info,name+'-complete-formal-game-activity-all-stores',proof);return proof;
}
async function tick(page:Page,a:any,before:Game,info:TestInfo,name:string){const accepted=await database(page),left=a.dueAt-await page.evaluate(()=>Date.now());expect(left).toBeGreaterThan(0);expect(left).toBeLessThanOrEqual(a.cycleMs);await page.clock.fastForward(left-1);expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await noArrival(page);await page.clock.fastForward(1);return saved(page,a,before,accepted,info,name);}
async function noArrival(page:Page){for(const id of ['jade-arrival','relic-result','configuration-arrival'])await expect(page.getByTestId(id)).toHaveCount(0);}
async function paint(page:Page,id:string){await expect.poll(async()=>{await page.clock.runFor(16);return page.getByTestId(id).isVisible();},{timeout:8000}).toBe(true);const seq=await page.getByTestId(id).getAttribute('data-sequence');expect(Number(seq)).toBeGreaterThan(0);return seq;}
async function observe(page:Page){await page.evaluate(()=>{const w=window as any,rows:any[]=[],seen=new WeakMap<Element,string>();const collect=()=>{for(const n of document.querySelectorAll('[data-testid=jade-arrival],[data-testid=relic-result],[data-testid=configuration-arrival]')){const seq=n.getAttribute('data-sequence')??'';if(seq&&seen.get(n)!==seq){seen.set(n,seq);rows.push({kind:n.getAttribute('data-testid'),sequence:seq,text:n.textContent,wall:Date.now()});}}};const observer=new MutationObserver(collect);observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['data-sequence']});w.__ta09Observer=observer;w.__ta09Arrivals=rows;});}
async function observed(page:Page){return page.evaluate(()=>(window as any).__ta09Arrivals??[]);}
async function holdWrite(page:Page){await page.evaluate(()=>new Promise<void>((accept,reject)=>{const r=indexedDB.open('chenyuan-playable-v1');r.onerror=()=>reject(r.error);r.onsuccess=()=>{const db=r.result,names=[...db.objectStoreNames],tx=db.transaction(names,'readwrite'),rows:any={};let remaining=names.length,held=true;const w=window as any;w.__ta09ReleaseWrite=()=>held=false;const repeat=()=>{const q=tx.objectStore('full-state').get('current');q.onsuccess=()=>{w.__ta09HeldGame=q.result;if(held)repeat();};};for(const name of names){rows[name]=[];const q=tx.objectStore(name).openCursor();q.onsuccess=()=>{if(q.result){rows[name].push({key:q.result.key,value:q.result.value});q.result.continue();}else if(--remaining===0){w.__ta09HeldDB={version:db.version,rows};repeat();accept();}};}tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error);};};}));}
async function quota(page:Page,kind:'cycle'|'start'|'configuration'='cycle'){await page.evaluate(kind=>{const w=window as any,put=IDBObjectStore.prototype.put;w.__ta09Rejected=[];w.__ta09RestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&(kind==='cycle'?this.name==='full-state'&&key==='current':this.name==='full-receipts'&&(kind==='start'?value?.input?.kind==='START':value?.format==='chenyuan-configuration-receipt'))){w.__ta09Rejected.push({key,value:structuredClone(value),wall:Date.now()});w.__ta09RestorePut();throw new DOMException('TA09 native '+kind+' quota fixture','QuotaExceededError');}return put.call(this,value,key!);};},kind);}
async function nativeWrites(page:Page){await page.evaluate(()=>{const w=window as any,put=IDBObjectStore.prototype.put;w.__ta09NativeWrites=[];w.__ta09NativeCompleted=null;w.__ta09RestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(value:any,key?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&this.name==='full-state'&&key==='current'){w.__ta09NativeWrites.push({value:structuredClone(value),key,wall:Date.now(),mono:performance.now(),mode:this.transaction.mode});this.transaction.addEventListener('complete',()=>w.__ta09NativeCompleted={wall:Date.now(),mono:performance.now()},{once:true});}return put.call(this,value,key!);};});}
async function nativeCycle(page:Page,kind:'learn'|'study'|'forge',before:Game,info:TestInfo,name:string,onRunning?:(a:any)=>Promise<void>){await nativeWrites(page);const began=await page.evaluate(()=>({wall:Date.now(),mono:performance.now()})),a=await begin(page,kind,false),accepted=await database(page),first=parseFloat(await page.getByTestId('training-countdown').innerText());expect(first).toBeGreaterThan(0);expect(first).toBeLessThanOrEqual(a.cycleMs/1000);await expect.poll(async()=>parseFloat(await page.getByTestId('training-countdown').innerText())).toBeLessThan(first);expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);expect(await page.evaluate(()=>(window as any).__ta09NativeWrites)).toEqual([]);await noArrival(page);if(onRunning)await onRunning(a);await expect.poll(()=>page.evaluate(()=>(window as any).__ta09NativeCompleted),{timeout:kind==='learn'?40000:75000}).not.toBeNull();const completed=await page.evaluate(()=>(window as any).__ta09NativeCompleted),proof=await saved(page,a,before,accepted,info,name),ended=await page.evaluate(()=>({wall:Date.now(),mono:performance.now(),writes:(window as any).__ta09NativeWrites}));expect(ended.mono-began.mono).toBeGreaterThanOrEqual(a.cycleMs);expect(completed.wall).toBeGreaterThanOrEqual(a.dueAt);expect(ended.writes).toHaveLength(1);expect(ended.writes[0].wall).toBeGreaterThanOrEqual(a.dueAt);expect(ended.writes[0].value).toEqual(proof.after);await attach(info,name+'-native-timing',{clock:'Native Chromium and forwarded original IDB put/native complete event; no virtual clock, no sleep',began,a,first,completed,ended,receipt:proof.receipt});return proof;}
