 const rail=page.getByTestId('study-queue-rail');await readonlyClick(page,'queue-mode-'+domain);await expect(rail).toHaveAttribute('data-domain',domain);while(await page.getByTestId('queue-prev').count()&&await page.getByTestId('queue-prev').isEnabled())await readonlyClick(page,'queue-prev');const found:string[]=[];
