async function at(page:Page,a:any,elapsed:number,kind:'jade'|'relic',phase:string,info:TestInfo,name:string){const target=a.startedAt+elapsed,now=await page.evaluate(()=>Date.now());expect(target).toBeGreaterThanOrEqual(now);await page.clock.fastForward(target-now);const actor=page.getByTestId(kind==='jade'?'jade-engraving':'relic-inscription-object');await expect(actor).toHaveAttribute('data-working','true');await expect(actor).toHaveAttribute('data-phase',phase);await objectGeometry(page,kind,info,name);}
async function configureOpen(page:Page,action:any){if(action.type==='SCHOOL'){await openHubFeature(page,'skills');await page.getByTestId('equipment-mode-school').click();await page.getByTestId('school-'+action.school).click();}else if(action.type==='EQUIP'){await skills(page,action.skill);await page.getByTestId('equip-'+action.skill).click();}else{await relic(page,action.relic);await page.getByTestId('equip-relic-'+action.relic).click();}await expect(page.getByTestId('configuration-dialog')).toBeVisible();}
async function configured(page:Page,action:any,before:Game,accepted:any,info:TestInfo,name:string){await expect(page.getByTestId('configuration-dialog')).toHaveCount(0);await expect(page.getByTestId('save-status')).toHaveText('已保存');const raw=await database(page),rows=raw.rows['full-receipts'].filter((r:any)=>r.value.format==='chenyuan-configuration-receipt'&&r.value.intent.command.expectedRevision===before.core.revision);expect(rows).toHaveLength(1);const receipt=rows[0].value,cmd=receipt.intent.command,formal=resolve(before,cmd);expect(cmd).toMatchObject({...action,runId:before.core.runId,expectedRevision:before.core.revision});expect(receipt.before).toEqual(before);expect(receipt.after).toEqual(formal.nextState);expect(receipt.result).toEqual(formal.result);expect(receipt.intent.expectedActivityId).toBeNull();expect(receipt.intent.expectedActivityRevision).toBeNull();expect(()=>validateConfigurationReceipt(receipt,formal.nextState)).not.toThrow();expect(await snapshot(page)).toEqual(formal.nextState);expect(stateValue(raw,'current')).toEqual(formal.nextState);expect(stateValue(raw,'previous')).toEqual(before);expect(stateValue(raw,'activity')).toBeNull();expect(raw.rows['full-receipts'].filter((r:any)=>r.key!==rows[0].key)).toEqual(accepted.rows['full-receipts']);for(const k of Object.keys(raw.rows).filter(k=>!['full-state','full-receipts'].includes(k)))expect(raw.rows[k],k).toEqual(accepted.rows[k]);expect(raw.rows['full-state'].filter((r:any)=>!['current','previous','activity'].includes(r.key))).toEqual(accepted.rows['full-state'].filter((r:any)=>!['current','previous','activity'].includes(r.key)));expect(formal.nextState.core.inventory).toEqual(before.core.inventory);expect(formal.nextState.core.player.stones).toBe(before.core.player.stones);expect(formal.nextState.core.world).toEqual(before.core.world);await expect(page.getByTestId('action-execution')).toHaveCount(0);await attach(info,name+'-instant-full-game-activity-cas-and-all-stores',{before,accepted,action,receipt,raw,formal});return{after:formal.nextState,raw,receipt,key:rows[0].key};}
async function instant(page:Page,action:any,before:Game,info:TestInfo,name:string){const accepted=await database(page);await configureOpen(page,action);expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await page.getByTestId('configuration-confirm').click();return configured(page,action,before,accepted,info,name);}

