test('TA09-A7 four artifact blueprints become distinct workpieces and only saved owned artifacts reveal their real cold art',async({page,browser},info)=>{
 const shapes:Record<string,string>={};for(const [index,id]of Object.keys(C.relics).entries()){const context=index?await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}):null,p=context?await context.newPage():page;try{const before=await load(p,preparedFixture(id));await relic(p,id);const actor=p.getByTestId('relic-inscription-object');await expect(actor).toHaveAttribute('data-owned','false');await expect(actor).toHaveAttribute('data-phase','still');await expect(actor.locator('.relic-cold-blank')).toHaveCount(1);await expect(actor.locator('.relic-cold-blank')).toHaveAttribute('data-art-state','ready');await expect(actor.locator('.relic-finished-art')).toHaveCount(0);await expect(p.getByTestId('production-relic-state')).toContainText('器谱冷胚示意');await frame(p,info,id+'-cold-unowned-blueprint');const raw=await database(p);await readonlyClick(p,'relic-object-inspect');await expect(p.getByRole('dialog')).toContainText('投入限额');await frame(p,info,id+'-full-original-budget');await p.getByRole('button',{name:'取消调整',exact:true}).click();await expect(p.getByRole('dialog')).toHaveCount(0);expect(await database(p)).toEqual(raw);const a=await begin(p,'forge'),accepted=await database(p);await at(p,a,6000,'relic','contact',info,id+'-tool-contact');await expect(actor.locator('.relic-workpiece')).toHaveAttribute('data-form',relicForms[id]);await expect(actor.locator('.relic-finished-art')).toHaveCount(0);await expect(actor.locator('.relic-tool')).toHaveAttribute('data-tool',relicForms[id]);const actualBlank=actor.locator('.relic-cold-blank');await expect(actualBlank).toHaveCount(1);await expect(actualBlank).toHaveAttribute('data-asset-id','relic-blank-'+id);await expect(actualBlank).toHaveAttribute('data-art-state','ready');shapes[id]=await actualBlank.locator('img').evaluate(image=>{const n=image as HTMLImageElement;const canvas=document.createElement('canvas');canvas.width=n.naturalWidth;canvas.height=n.naturalHeight;const ctx=canvas.getContext('2d')!;ctx.drawImage(n,0,0);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data,rows=new Array(canvas.height).fill(0),cols=new Array(canvas.width).fill(0);for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++)if(data[(y*canvas.width+x)*4+3]>16){rows[y]++;cols[x]++;}if(!n.complete||canvas.width!==512||canvas.height!==512||rows.reduce((a,b)=>a+b,0)<=0)throw Error('Actual blank image must be loaded and nonempty');return JSON.stringify({rows,cols});});await at(p,a,30000,'relic','engraving',info,id+'-half-inscribed');await frame(p,info,id+'-distinct-half-inscribed-workpiece');await at(p,a,54000,'relic','forming',info,id+'-forming-before-save');await p.clock.fastForward(a.dueAt-await p.evaluate(()=>Date.now())-1);expect(await snapshot(p)).toEqual(before);expect(await database(p)).toEqual(accepted);await holdWrite(p);try{await p.clock.fastForward(1);await expect(p.getByTestId('save-status')).toHaveText('保存中');expect(await p.evaluate(()=>(window as any).__ta09HeldGame)).toEqual(before);await expect(actor).toHaveAttribute('data-phase','sealing');await expect(actor).toHaveAttribute('data-working','false');await expect(actor.locator('.relic-tool')).toHaveCSS('opacity','0');await expect(actor.locator('.relic-sealing')).toHaveAttribute('data-sealing','true');await expect(actor.locator('.relic-finished-art')).toHaveCount(0);await noArrival(p);await frame(p,info,id+'-native-sealing-before-art-is-owned');}finally{await p.evaluate(()=>(window as any).__ta09ReleaseWrite());}const proof=await saved(p,a,before,accepted,info,id+'-saved-once');await paint(p,'relic-result');await resultClearance(p,'relic-result',info,id);expect(proof.after.ownedRelics).toContain(id);expect(proof.after.loadout.relic).toBe(before.loadout.relic);await expect(actor).toHaveAttribute('data-owned','true');await expect(actor).toHaveAttribute('data-bound','false');await expect(actor.locator('.relic-finished-art')).toHaveCount(1);await expect(p.getByTestId('production-start')).toHaveCount(0);await expect(p.getByTestId('equip-relic-'+id)).toBeEnabled();await frame(p,info,id+'-owned-not-automatically-bound');await stable(p,proof);}finally{if(context){await isolatedDiagnostics(p,info);await context.close();}}}expect(new Set(Object.values(shapes)).size).toBe(4);
});

test('TA09-A8 native sixty-second positive-cost forging saves full material and month costs before revealing an unbound artifact',async({page},info)=>{
 test.setTimeout(90000);const before=await load(page,preparedFixture('jade_seal'),false);await relic(page,'jade_seal');await observe(page);const proof=await nativeCycle(page,'forge',before,info,'native-sixty-second-positive-forge',async()=>{await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-working','true');await expect(page.getByTestId('relic-inscription-object').locator('.relic-workpiece')).toHaveAttribute('data-form','seal');await expect(page.getByTestId('relic-inscription-object').locator('.relic-finished-art')).toHaveCount(0);await objectGeometry(page,'relic',info,'native-forge-actual-blank-and-tool');await frame(page,info,'native-forge-actual-blank-and-tool');});await expect(page.getByTestId('relic-result')).toBeVisible();await resultClearance(page,'relic-result',info,'native-positive-forge');expect(proof.after.core.player.stones).toBe(before.core.player.stones-C.relics.jade_seal.stones);expect(proof.after.core.inventory.jade).toBe(before.core.inventory.jade-4);expect(proof.after.core.world.elapsedMonths).toBe(before.core.world.elapsedMonths+2);expect(proof.after.ownedRelics).toEqual([...before.ownedRelics,'jade_seal']);expect(proof.after.loadout.relic).toBe(before.loadout.relic);await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-owned','true');await expect(page.getByTestId('relic-inscription-object')).toHaveAttribute('data-bound','false');await expect(page.getByTestId('equip-relic-jade_seal')).toBeEnabled();await frame(page,info,'native-forge-owned-not-bound');const raw=await database(page);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await relic(page,'jade_seal');await noArrival(page);expect(await snapshot(page)).toEqual(proof.after);expect(await database(page)).toEqual(raw);
});

test('TA09-A9 paid LEARN cycle and FORGE admission quota failures retain the exact original intent for one first successful retry',async({page,browser},info)=>{
 for(const domain of ['learn','forge'] as const){const context=domain==='forge'?await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}):null,p=context?await context.newPage():page;try{const before=await load(p,domain==='learn'?goldenFixture():preparedFixture('frost_sword'));if(domain==='learn')await learnPlan(p,['sword_guard']);else await relic(p,'frost_sword');await observe(p);let a:any,accepted:any;if(domain==='learn'){a=await begin(p,'learn');accepted=await database(p);await p.clock.fastForward(a.dueAt-await p.evaluate(()=>Date.now())-1);expect(await snapshot(p)).toEqual(before);expect(await database(p)).toEqual(accepted);await quota(p,'cycle');await p.clock.fastForward(1);}else{accepted=await database(p);await quota(p,'start');await p.getByTestId('production-start').click();}await expect(p.getByTestId('error')).toContainText('存储空间不足');const rejected=await p.evaluate(()=>(window as any).__ta09Rejected);expect(rejected).toHaveLength(1);expect(await snapshot(p)).toEqual(before);expect(await database(p)).toEqual(accepted);await cold(p,domain==='learn'?'jade':'relic');await noArrival(p);await expect(p.getByTestId(domain==='learn'?'preparation-start':'production-start')).toBeDisabled();await frame(p,info,domain+'-quota-full-budget-and-cold-object');await p.getByTestId('retry').click();if(domain==='forge'){a=await running(p,'forge');const admissionDB=await database(p),starts=admissionDB.rows['full-receipts'].filter((r:any)=>r.value.input?.kind==='START'&&r.value.activity.id===a.id);expect(starts).toHaveLength(1);const admitted=starts[0].value,original=rejected[0].value;expect(starts[0].key).toBe(rejected[0].key);expect(admitted.input).toEqual(original.input);expect(admitted.fingerprint).toBe(original.fingerprint);expect(admitted.fingerprint).toBe(canonicalFingerprint(original.input));expect(admitted.command).toBeNull();expect(admitted.result).toBeNull();expect(admitted.activity).toEqual(a);const normalized=structuredClone(admitted);normalized.activity.id=original.activity.id;normalized.activity.nextCommand.commandId=original.activity.nextCommand.commandId;expect(normalized).toEqual(original);const formalAdmission=createActivity(before,original.input.plan,{id:a.id,ownerId:original.input.mutation.ownerId,commandId:original.input.mutation.commandId,now:original.activity.startedAt});expect(a).toEqual(formalAdmission);expect(()=>validateActivityReceipt(admitted,before)).not.toThrow();const expectedAdmission=structuredClone(accepted),activityRow=expectedAdmission.rows['full-state'].find((r:any)=>r.key==='activity');if(activityRow)activityRow.value=formalAdmission;else expectedAdmission.rows['full-state'].push({key:'activity',value:formalAdmission});expectedAdmission.rows['full-receipts'].push(starts[0]);for(const store of ['full-state','full-receipts'])expectedAdmission.rows[store].sort((x:any,y:any)=>x.key<y.key?-1:x.key>y.key?1:0);expect(admissionDB).toEqual(expectedAdmission);await attach(info,'forge-original-start-retry-complete-authorization-and-native-stores',{original,rejected,admitted,formalAdmission,before:accepted,admissionDB,onlyUncommittedCandidateIdentityPaths:['activity.id','activity.nextCommand.commandId']});expect(await snapshot(p)).toEqual(before);await noArrival(p);accepted=await database(p);await p.clock.fastForward(a.dueAt-await p.evaluate(()=>Date.now())-1);expect(await database(p)).toEqual(accepted);await p.clock.fastForward(1);}const proof=await saved(p,a,before,accepted,info,domain+'-original-intent-first-success');await paint(p,domain==='learn'?'jade-arrival':'relic-result');await resultClearance(p,domain==='learn'?'jade-arrival':'relic-result',info,domain+'-retry');expect(proof.receipt.command.commandId).toBe(a.nextCommand.commandId);expect((await observed(p)).filter((r:any)=>r.kind===(domain==='learn'?'jade-arrival':'relic-result'))).toHaveLength(1);await frame(p,info,domain+'-same-intent-first-real-saved');await stable(p,proof);await p.reload();await expect(p.getByTestId('save-status')).toHaveText('已保存');if(domain==='learn')await skills(p,'sword_guard');else await relic(p,'frost_sword');await noArrival(p);expect(await database(p)).toEqual(proof.raw);}finally{if(context){await isolatedDiagnostics(p,info);await context.close();}}}
});

test('TA09-A10 pause pending hidden scenes and same-id foreign generations clear work and old seals while full history remains authoritative',async({page,context},info)=>{
 const before=await load(page,goldenFixture());await learnPlan(page,['sword_guard','sword_still','sword_echo'],444,7);await selectLearningSkill(page,'sword_guard');await observe(page);const a=await begin(page,'learn'),accepted=await database(page);await page.clock.fastForward(1000);await holdWrite(page);try{await page.getByTestId('training-pause').click();await expect(page.locator('[data-testid=training-activity][data-running=false]')).toBeVisible();expect(await page.evaluate(()=>(window as any).__ta09HeldGame)).toEqual(before);expect(await page.evaluate(()=>(window as any).__ta09HeldDB)).toEqual(accepted);await cold(page,'jade');await frame(page,info,'pause-request-withdraws-tool-before-pause-transaction');}finally{await page.evaluate(()=>(window as any).__ta09ReleaseWrite());}await expect.poll(async()=>(await activity(page)).status).toBe('paused');expect(await snapshot(page)).toEqual(before);const other=await otherPage(page,context);try{await page.getByTestId('training-resume').click();const resumed=await running(page,'learn');expect(resumed.id).toBe(a.id);expect(resumed.generation).toBeGreaterThan(a.generation);const visibleDB=await database(page);await page.evaluate(()=>{const old=Object.getOwnPropertyDescriptor(document,'hidden'),w=window as any;Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});w.__ta09RestoreVisibility=()=>{if(old)Object.defineProperty(document,'hidden',old);else delete (document as any).hidden;document.dispatchEvent(new Event('visibilitychange'));};document.dispatchEvent(new Event('visibilitychange'));});await cold(page,'jade');await attach(info,'controlled-document-visibility-boundary',{seam:'Readonly own hidden getter plus normal visibilitychange event, restored immediately; not an OS background or environment test',activity:resumed});expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(visibleDB);await page.evaluate(()=>(window as any).__ta09RestoreVisibility());await expect(page.getByTestId('jade-engraving')).toHaveAttribute('data-working','true');expect((await activity(page)).nextCommand).toEqual(resumed.nextCommand);const first=await tick(page,resumed,before,info,'own-scroll-before-hidden');await paint(page,'jade-arrival');await page.getByTestId('tab-1').click();await noArrival(page);await skills(page,'sword_still');await noArrival(page);const prior=await activity(page);await other.getByTestId('training-resume').click();const taken=await running(other,'learn');expect(taken.id).toBe(prior.id);expect(taken.ownerId).not.toBe(prior.ownerId);expect(taken.generation).toBeGreaterThan(prior.generation);expect(taken.plan).toEqual(prior.plan);await expect(page.locator('[data-testid=training-activity][data-generation="'+taken.generation+'"]')).toBeVisible();await cold(page,'jade');expect(await page.evaluate(()=>document.hidden)).toBe(false);expect(await snapshot(page)).toEqual(first.after);const second=await tick(other,taken,first.after,info,'foreign-second-scroll');await expect.poll(async()=>(await activity(page)).completedCycles).toBe(2);expect(await snapshot(page)).toEqual(second.after);await noArrival(page);const lastA=await running(other,'learn'),last=await tick(other,lastA,second.after,info,'foreign-third-scroll');await expect.poll(async()=>(await activity(page)).completedCycles).toBe(3);expect(await snapshot(page)).toEqual(last.after);await noArrival(page);const raw=await database(page);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await skills(page,'sword_guard');await cold(page,'jade');await expect(page.getByTestId('hub-receipt')).toBeEnabled();await readonlyClick(page,'hub-receipt');await readonlyClick(page,'activity-history-open');await expect(page.getByTestId('activity-history-row')).toHaveCount(1);await expect(page.getByTestId('activity-history')).toContainText(C.skills.sword_guard.name);await noArrival(page);expect(await snapshot(page)).toEqual(last.after);expect(await database(page)).toEqual(raw);await page.clock.fastForward(120000);expect(await snapshot(page)).toEqual(last.after);expect(await database(page)).toEqual(raw);await attach(info,'same-id-foreign-owner-history-and-seals',{a,resumed,prior,taken,first:first.receipt,second:second.receipt,last:last.receipt,observed:await observed(page)});}finally{await isolatedDiagnostics(other,info);await other.close();}
});

